data.command:
/bin/bash -lc 'set -e
BASE=c56d433e8a99a82babf50aecb3e6fec48410e2a2
SNAP=$("$HORIZON_GIT" rev-parse HEAD)
tmp=$(mktemp -d /tmp/ajcr-final-census-XXXXXX)
mkdir -p "$tmp/base" "$tmp/head"
"$HORIZON_GIT" archive "$BASE" MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian | tar -x -C "$tmp/base"
"$HORIZON_GIT" archive "$SNAP" MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian | tar -x -C "$tmp/head"
BASE="$BASE" SNAP="$SNAP" CENSUS_TMP="$tmp" python3 - <<'"'PY'
import os
from pathlib import Path
from archon_horizon.search.index import extract_declarations
root=Path(os.environ[\"CENSUS_TMP\"])
projects={
 \"AJC\":\"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian\",
 \"AJCR\":\"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian\",
}
def split(s):
 p=b=c=0
 for i,ch in enumerate(s):
  if ch==\"(\": p+=1
  elif ch==\")\": p=max(0,p-1)
  elif ch==\"[\": b+=1
  elif ch==\"]\": b=max(0,b-1)
  elif ch==\"{\": c+=1
  elif ch==\"}\": c=max(0,c-1)
  elif ch==\":\" and p==b==c==0: return s[:i],s[i+1:]
 return s,\"\"
def run(which,rel):
 files=sorted((root/which/rel).rglob(\"*.lean\")); ds=[]; raw=0
 for f in files:
  t=f.read_text(); raw+=t.count(\"(rep :\")
  ds += extract_declarations(t,library=rel,file=str(f.relative_to(root/which)))
 rows=[]
 for d in ds:
  a,z=split(d.signature); rows.append((d.file,d.name,a.count(\".RepresentableBy\"),z.count(\".RepresentableBy\")))
 return (len(files),len(ds),raw,sum(\"(rep :\" in d.signature for d in ds),sum(d.signature.count(\"(rep :\" for d in ds),
         sum(x[2] for x in rows),sum(x[2]>0 for x in rows),sum(x[3] for x in rows),
         sum(x[3]>0 for x in rows),sum(x[3]>0 and x[2]==0 for x in rows),rows)
for n,rel in projects.items():
 B=run(\"base\",rel); H=run(\"head\",rel)
 labels=[\"files\",\"decls\",\"raw\",\"strict_decls\",\"strict_occ\",\"input_occ\",\"input_decls\",\"result_occ\",\"result_decls\",\"direct\"]
 print(n)
 for i,l in enumerate(labels): print(f\"  {l}: {B[i]} -> {H[i]} (delta {H[i]-B[i]:+d})\")
 bkeys={(r[0],r[1]) for r in B[-1]}
 print(\"  new relevant:\")
 for f,name,ic,rc in H[-1]:
  if (f,name) not in bkeys and (ic or rc):
   print(f\"    {f}:{name}: input={ic} result={rc}\")
PY
rm -rf \""'$tmp"'
